+	u32 rx_page_size = fbnic_qcfg_rx_page_size(qcfg);
+	int err;
 
-	if (!netif_running(dev))
-		return fbnic_alloc_qt_page_pools(fbn, qt, idx);
+	if (!netif_running(dev)) {
